// Validation du formulaire du site Studio (champs : nom, email, societe, type_projet, echeance, message, consentement, langue, piece, horodatage, site_web)
const b = $input.first().json.body || {};
const h = $input.first().json.headers || {};
const s = (v, n) => String(v ?? '').trim().slice(0, n);
const nom = s(b.nom, 100), email = s(b.email, 254), societe = s(b.societe, 100), type_projet = s(b.type_projet, 40), echeance = s(b.echeance, 40), message = s(b.message, 3000), piece = s(b.piece, 80);
const langue = s(b.langue, 2) === 'en' ? 'en' : 'fr';
// Pot de miel rempli, ou formulaire envoyé moins de 3 s après l'ouverture : robot. On répond comme si tout allait bien, sans envoyer.
const spam = !!s(b.site_web, 10) || (Number(b.horodatage) > 0 && Date.now() - Number(b.horodatage) < 3000);
const ok = nom.length >= 2 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) && message.length >= 20 && b.consentement === 'oui' && !!type_projet && !!echeance;
const json = /application\/json/i.test(String(h.accept || ''));
const site = 'https://studio.madigitalagency.net';
return [{ json: { ok, spam, envoyer: ok && !spam, json, langue, nom, email, societe, type_projet, echeance, message, piece,
  redirect: langue === 'en' ? site + '/en/contact/thanks/' : site + '/contact/merci/',
  retour: langue === 'en' ? site + '/en/contact/?erreur=1' : site + '/contact/?erreur=1',
  ip: h['x-real-ip'] || h['x-forwarded-for'] || '', date: new Date().toISOString() } }];

